#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
PASQAL two-atom L3+L4 standalone Colab audit.

One file, no password, no companion modules. It embeds the two-atom
propagator, matched-fibre generator, covariant quartic tensor audit, and
analytic remainder-bound certificate.

Upload and run:
    %run /content/pasqal_L3_L4_standalone_colab.py

It also supports direct copy/paste into a Colab cell where __file__ is absent.
"""

from __future__ import annotations

import base64
import gzip
import sys
import types

_EMBEDDED = {
    "pasqal_two_atom_matched_fibre_test": "",
    "pasqal_two_atom_q2_prospective_ranking": "",
    "_l3_l4_main": "",
}


def _source(key: str) -> bytes:
    return gzip.decompress(base64.b64decode(_EMBEDDED[key]))


def _install(name: str) -> None:
    module = types.ModuleType(name)
    module.__file__ = f"<embedded:{name}>"
    module.__package__ = ""
    sys.modules[name] = module
    exec(compile(_source(name), module.__file__, "exec"), module.__dict__)


def main() -> None:
    print(
        "[start] L3 covariant tensor + L4 remainder-bound audit; "
        "expected runtime about 30-90 seconds...",
        flush=True,
    )
    _install("pasqal_two_atom_matched_fibre_test")
    _install("pasqal_two_atom_q2_prospective_ranking")
    runtime_file = globals().get("__file__", "<colab-notebook-cell>")
    namespace = {
        "__name__": "__main__",
        "__file__": runtime_file,
        "__package__": None,
    }
    exec(
        compile(
            _source("_l3_l4_main"),
            "<embedded:pasqal_two_atom_L3_L4_tensor_bound_audit>",
            "exec",
        ),
        namespace,
    )


if __name__ == "__main__":
    main()

